
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_pbe_molb0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_pbe_molb0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.318868733902091e+00, -3.256922429152602e+00, -3.170184060116220e+00, -3.050163201638838e+00, -2.886900780797884e+00, -2.670202487044366e+00, -2.392510430850339e+00, -2.053928475076999e+00, -1.668102015130074e+00, -1.260791273617185e+00, -8.516039567139353e-01, -5.765378734398877e-01, -5.003783509339502e-01, -4.136085910974756e-01, -3.012479623608989e-01, -1.920317035034902e-01, -1.023091984838494e-01, -3.727711288678582e-02, -8.110407574365418e-03, -9.121537402500759e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


